import{_ as a,o,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Internacionalização e acessibilidade","description":"","frontmatter":{"title":"Internacionalização e acessibilidade","docId":"developer.i18n-accessibility","translationKey":"developer.i18n-accessibility","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2c74fcefd1d28353b1135c547b2e3e6ae852af8b683350011732d10c364f9323","translationRevision":"2044bf71c9d7c366f13f360f640ca55c335538d586385522f2cee35a4752c8c1","order":120},"headers":[],"relativePath":"pt/developer/i18n-accessibility.md","filePath":"pt/developer/i18n-accessibility.md","lastUpdated":1794611623000}'),t={name:"pt/developer/i18n-accessibility.md"};function n(r,e,c,d,l,p){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="internationalization-and-accessibility" tabindex="-1">Internacionalização e acessibilidade <a class="header-anchor" href="#internationalization-and-accessibility" aria-label="Permalink to &quot;Internacionalização e acessibilidade {#internationalization-and-accessibility}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Adicione uma tela que continue compreensível nos idiomas disponíveis e utilizável por teclado, toque e tecnologia assistiva. Leia <a href="./frontend.html">camadas do frontend</a> e use a interface compartilhada existente. Os idiomas do aplicativo em execução e as edições publicadas da documentação são sistemas separados.</p><h2 id="add-localized-content" tabindex="-1">Adicione conteúdo localizado <a class="header-anchor" href="#add-localized-content" aria-label="Permalink to &quot;Adicione conteúdo localizado {#add-localized-content}&quot;">​</a></h2><p>O catálogo do aplicativo fica em <code>src/web/shared/i18n/</code>. O inglês é a alternativa tipada; os outros catálogos disponíveis carregam sob demanda. <code>activateLocale</code> carrega as mensagens escolhidas e atualiza <code>document.documentElement.lang</code>. Armazene uma preferência de idioma pelo store de idioma existente em vez de gravar outra chave no armazenamento local.</p><ol><li>Adicione a chave semântica da mensagem ao catálogo em inglês e aos catálogos/módulos equivalentes disponíveis.</li><li>Mantenha IDs de API, caminhos de eventos e identificadores de recursos armazenados estáveis; traduza seus rótulos visíveis.</li><li>Use interpolação para texto variável e auxiliares compartilhados de internacionalização para valores de exibição.</li><li>Para descritores de plugins, use o contrato existente de texto localizado <code>{default,i18key}</code> e os catálogos mesclados pelo host. Nunca renderize strings traduzidas ou fornecidas por plugins como HTML.</li></ol><h2 id="preserve-control-semantics" tabindex="-1">Preserve a semântica dos controles <a class="header-anchor" href="#preserve-control-semantics" aria-label="Permalink to &quot;Preserve a semântica dos controles {#preserve-control-semantics}&quot;">​</a></h2><p>Prefira <code>BaseTextField</code>, <code>BaseFormRow</code>, <code>BaseDialog</code>, abas e componentes de status. Um texto de exemplo no campo não substitui um rótulo acessível. Botões com ícones precisam de um nome localizado. A validação deve identificar o campo e expor o estado inválido; não comunique falhas apenas pela cor. Preserve retorno de foco do diálogo, comportamento de Escape, seleção pelo teclado e contornos visíveis de foco.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalogs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BaseDialog</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span></code></pre></div><p>Para revisão manual, percorra todo o fluxo com Tab, abra/feche o diálogo, troque de idioma enquanto ele estiver aberto e repita em largura estreita. Ações de status reveladas ao passar o ponteiro também devem aparecer com foco de teclado e continuar disponíveis por toque.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Tipagem de catálogos e verificações de paridade detectam chaves ausentes; controles compartilhados fornecem comportamento implementado de teclado e ARIA. Eles não constituem uma certificação geral de acessibilidade de toda tela composta. Rankings permanece oculto mesmo quando existem strings traduzidas.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Se aparecer texto não traduzido, confira o carregamento sob demanda dos catálogos e a grafia exata da chave antes de adicionar alternativas em inglês nos componentes. Se o foco desaparecer, inspecione o controle que recebe atributos encaminhados e o alvo de retorno do diálogo. A <a href="https://github.com/nglmercer/TikTools-app/blob/remake/src/web/shared/i18n/i18n.ts" target="_blank" rel="noreferrer">implementação i18n</a> e os testes de componentes definem o comportamento atual; <a href="./components/">componentes</a> explica os pontos de entrada compartilhados.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Detecção: <code>tiktok-live-locale</code> salvo → <code>navigator.languages</code> → inglês. <code>normalizeLocale</code> normaliza regiões e <code>jp</code> → <code>ja</code>. Códigos/regiões: <code>en/en-US</code>, <code>es/es-ES</code>, <code>pt/pt-BR</code>, <code>fr/fr-FR</code>, <code>zh/zh-CN</code>, <code>ja/ja-JP</code>; use formatCount/formatDate de <code>intl.ts</code>. <code>activateLocale</code> carrega mensagens/lang; <code>useLocaleStore().setLocale</code> também persiste e prepara preferências de melhor esforço. Use store nos ajustes. Inglês é fallback; zh/ja carregam mensagens host. Novo idioma exige supported-locales, loaders, catálogos/host, regiões, testes de preferências e chaves/placeholders/plurais/compilação e rotas docs/site. Preserve IDs/API e parâmetros.</p><p>Use tokens de espaço/tipo/controle/foco/camadas. Ponteiro grosso ou largura menor que 700px eleva controles a 44px; navegação muda abaixo de 900px e linhas abaixo de 600px independentemente. Movimento reduzido zera durações. Teste toque também em desktop largo. O app é escuro globalmente; override claro só vale para JSON.</p><p>Teclado: abas usam setas/Home/End com seleção automática; selects setas/Home/End/Enter e Escape cancela; menus devolvem foco ao acionador. Diálogos usam showModal nativo, mas <code>closable=false</code> bloqueia Escape e fechar desmonta conteúdo. Guarde rascunhos no proprietário e confira foco inicial/retorno. Botão ícone exige <code>label</code>; <code>hint</code>/tooltip explica, não nomeia. Tooltip aguarda 500ms em hover/foco, fecha com Escape e usa top layer do diálogo. Revise teclado/assistência reais; testes unitários não certificam tela inteira.</p>`,18)])])}const u=a(t,[["render",n]]);export{h as __pageData,u as default};
